package template

import (
	"context"
	"errors"
	"fmt"
	"io"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

// SubscriptionRecord is the committed trace of one message-ref parameter's
// resolution: which registry message the component subscribes to, pinned to
// the schema version that was the registry's default at scaffold time. It
// travels in the scaffold record so later commands can compare what the
// component was scaffolded against with what the registry now declares.
type SubscriptionRecord struct {
	// Parameter is the message-ref template parameter that held the
	// reference.
	Parameter string `json:"parameter"`
	// Message is the message's full xid — unambiguous where a bare message
	// id is not.
	Message string `json:"message"`
	// SchemaID and SchemaVersion come from the schema resource the
	// message's dataschemaxid pointed at. Empty when that reference dangles
	// — the registry keeps unresolved references with a warning, and the
	// record mirrors what the registry actually said.
	SchemaID      string `json:"schemaid,omitempty"`
	SchemaVersion string `json:"schemaVersion,omitempty"`
}

// messageRefFields returns the template's message-ref parameters in
// declaration order.
func messageRefFields(t *Template) []FieldSpec {
	var refs []FieldSpec
	for _, f := range t.Fields() {
		if f.MessageRef {
			refs = append(refs, f)
		}
	}
	return refs
}

// fetchMessageRegistry builds a client for opts and fetches the export
// document. It runs only when the template declares a message-ref
// parameter — templates without one never touch the network for this.
func fetchMessageRegistry(ctx context.Context, opts CreateOptions) (*xregistry.Export, error) {
	client, err := xregistry.NewClient(opts.RegistryURL, xregistry.WithUserAgent(opts.UserAgent))
	if err != nil {
		return nil, err
	}
	doc, err := client.Export(ctx)
	if err != nil {
		return nil, fmt.Errorf("resolve message reference: %w", err)
	}
	return doc, nil
}

// missingRegistryNote is what an interactive create is owed when the
// template offers a subscription and no registry is configured: without it
// the message-ref prompt simply never appears, and the developer cannot
// tell an unconfigured registry from a template that has no registry path.
// Only an interactive run is told, because only that run would have been
// offered a list. A non-interactive create was never going to see one, and
// a reference it cannot resolve already fails loudly.
func missingRegistryNote(refs []FieldSpec, registryURL string, prompter Prompter) string {
	if len(refs) == 0 || registryURL != "" || prompter == nil {
		return ""
	}
	return "no message registry configured; this template's subscription parameter has no pick list\n" +
		"pass --registry-url, set INTROPY_REGISTRY_URL, or add registryUrl to the config file\n"
}

// errNoRegistryConfigured reports a message-ref value that cannot be
// validated because no registry is configured. It is only ever returned
// when a reference was actually given — a template that merely offers the
// parameter must not demand a registry from users who wire by hand.
var errNoRegistryConfigured = errors.New("template declares a message registry reference but no registry is configured\npass --registry-url, set INTROPY_REGISTRY_URL, or add registryUrl to the config file")

// messageRefValuePresent reports whether any message-ref parameter ended
// up with a value — the condition under which the registry is mandatory
// rather than a suggestion source.
func messageRefValuePresent(refs []FieldSpec, values map[string]any) bool {
	for _, f := range refs {
		if v, ok := values[f.Name]; ok && !isEmpty(v) {
			return true
		}
	}
	return false
}

// messageIDs lists every message id in the export, sorted, for the
// message-ref prompt's pick list. A nil export yields none, which is what
// cancels the prompt: the list is all the registry contributes at this
// stage, and validation and expansion happen after resolution, in
// resolveMessageRefs.
func messageIDs(doc *xregistry.Export) []string {
	if doc == nil {
		return nil
	}
	var ids []string
	for _, g := range doc.MessageGroups {
		for id := range g.Messages {
			ids = append(ids, id)
		}
	}
	sort.Strings(ids)
	return ids
}

// resolveMessageRefs validates each message-ref parameter's value against
// the registry and expands it into the wiring values the skeleton renders:
// the producing endpoint's channel becomes topic and pubsub, and an unset
// contract gets a suggestion derived from the payload schema's id. The
// returned records describe what was resolved, for the scaffold record.
//
// The registry is the source of truth for where a message flows, and a
// silent override in either direction would hide a real disagreement, so
// an existing topic or pubsub is handled by where it came from: identical
// is accepted; a conflicting --set is an error naming both; anything else
// (a template default, a spec.values derivation, a values file) yields to
// the registry with a note, because those layers declare conventions, not
// intent about this message. The contract is different — it is
// developer-owned (the registry names a schema document, not a type), so a
// present contract always stands and the registry only fills a gap, noted
// on stderr so the value never lands invisibly.
func resolveMessageRefs(t *Template, values map[string]any, doc *xregistry.Export, sets map[string]any, notes io.Writer) ([]SubscriptionRecord, error) {
	var subs []SubscriptionRecord
	for _, f := range messageRefFields(t) {
		raw, ok := values[f.Name]
		if !ok {
			// Optional and unanswered: no subscription to record.
			continue
		}
		ref, ok := raw.(string)
		if !ok || ref == "" {
			return nil, fmt.Errorf("parameter %q must be a message id or xid (string), got %v", f.Name, raw)
		}
		sub, err := resolveMessageRef(f.Name, ref, values, doc, sets, notes)
		if err != nil {
			return nil, err
		}
		subs = append(subs, sub)
	}
	return subs, nil
}

func resolveMessageRef(param, ref string, values map[string]any, doc *xregistry.Export, sets map[string]any, notes io.Writer) (SubscriptionRecord, error) {
	r, err := doc.ResolveMessage(ref)
	var nf *xregistry.MessageNotFoundError
	if errors.As(err, &nf) {
		return SubscriptionRecord{}, fmt.Errorf("%w\n%s", err, knownMessagesMessage(ref, doc))
	}
	if err != nil {
		// An ambiguous bare id already carries its remediation.
		return SubscriptionRecord{}, err
	}

	pubsub, topic, err := producerChannel(doc, r.Group.MessageGroupID, r.Message.Xid)
	if err != nil {
		return SubscriptionRecord{}, err
	}
	if err := injectWiringValue(values, KeyTopic, topic, r.Message.Xid, sets, notes); err != nil {
		return SubscriptionRecord{}, err
	}
	if err := injectWiringValue(values, KeyPubsub, pubsub, r.Message.Xid, sets, notes); err != nil {
		return SubscriptionRecord{}, err
	}

	sub := SubscriptionRecord{Parameter: param, Message: r.Message.Xid}
	if v := r.Version; v != nil && v.DataschemaXid != "" {
		if s, serr := doc.ResolveSchema(v.DataschemaXid); serr == nil {
			sub.SchemaID = s.Schema.SchemaID
			if s.Version != nil {
				sub.SchemaVersion = s.Version.VersionID
			}
			suggestContract(values, s.Schema.SchemaID, notes)
		}
	}
	return sub, nil
}

// injectWiringValue sets a wiring value from the registry. An identical
// value already present is accepted. A conflicting one is an error when it
// came from --set — the user stated intent about this message — and a
// noted override otherwise, since defaults and derived values declare
// conventions the registry's fact about this message outranks.
func injectWiringValue(values map[string]any, key, want, messageXid string, sets map[string]any, notes io.Writer) error {
	existing, ok := values[key]
	if !ok || existing == nil || existing == "" {
		values[key] = want
		return nil
	}
	if s, _ := existing.(string); s == want {
		return nil
	}
	if _, explicit := sets[key]; explicit {
		return fmt.Errorf("%s: the registry declares %q for %s, but the values set %q\nchange --set %s= to match the registry, or fix the registry's channel", key, want, messageXid, existing, key)

		return fmt.Errorf("%s: the registry declares %q for %s, but the values set %q\nchange --set %s= to match the registry, or fix the registry's channel", key, want, messageXid, existing, key)
	}
	values[key] = want
	if notes != nil {
		fmt.Fprintf(notes, "%s: %s (from the message registry; was %q)\n", key, want, existing)
	}
	return nil
}

// suggestContract fills an unset contract parameter with a name derived
// from the schema id. The registry names a schema document, not a type, so
// this is a suggestion — a contract the developer already set always
// stands, and the fill is noted so it never lands invisibly.
func suggestContract(values map[string]any, schemaID string, notes io.Writer) {
	if existing, ok := values[KeyContract]; ok && existing != nil && existing != "" {
		return
	}
	suggestion := SuggestContractName(schemaID)
	if suggestion == "" {
		return
	}
	values[KeyContract] = suggestion
	if notes != nil {
		fmt.Fprintf(notes, "%s: %s (suggested from the message schema; override with --set %s=<value>)\n", KeyContract, suggestion, KeyContract)
	}
}

// SuggestContractName derives a type name from a schema id: the version
// suffix is stripped and the kebab-case remainder is Pascal-cased
// ("product-export.v1" → "ProductExport"). It is a prompt-time suggestion,
// not a guarantee — no type by this name exists until it is written or
// generated, which is why the developer can always override it.
func SuggestContractName(schemaID string) string {
	base := schemaID
	if i := strings.LastIndex(base, ".v"); i > 0 && allDigits(base[i+2:]) {
		base = base[:i]
	}
	var b strings.Builder
	for _, part := range strings.Split(base, "-") {
		if part == "" {
			continue
		}
		b.WriteString(strings.ToUpper(part[:1]))
		b.WriteString(part[1:])
	}
	return b.String()
}

func allDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

// producerChannel resolves where a message group's messages flow: the
// channel of the producing endpoint. Several producers publish the same
// group's messages on their own channels; the sorted-first one is the
// deterministic pick until the registry grows a way to declare the
// canonical channel.
func producerChannel(doc *xregistry.Export, groupXid, messageXid string) (pubsub, topic string, err error) {
	producers := doc.ProducerEndpointsFor(groupXid)
	if len(producers) == 0 {
		return "", "", fmt.Errorf("message %s has no producer endpoint declared in the registry\ndeclare a producer endpoint for %s before scaffolding a subscriber", messageXid, groupXid)
	}
	pubsub, topic, err = xregistry.SplitChannel(producers[0].Channel)
	if err != nil {
		return "", "", fmt.Errorf("producer endpoint %s: %w", producers[0].EndpointID, err)
	}
	return pubsub, topic, nil
}

// PreviewWiring reports what resolving one registry message would inject
// at create time, without touching any values: the channel's pubsub and
// topic, and the contract name the payload schema suggests. Forms use it
// to show the routing a message pick implies before the pick is
// committed. A message without a resolvable channel yields the zero
// preview and no error — the create flow reports that properly when the
// message is actually picked.
func PreviewWiring(doc *xregistry.Export, messageID string) MessageWiring {
	r, err := doc.ResolveMessage(messageID)
	if err != nil {
		return MessageWiring{}
	}
	var w MessageWiring
	if pubsub, topic, err := producerChannel(doc, r.Group.MessageGroupID, r.Message.Xid); err == nil {
		w.Pubsub, w.Topic = pubsub, topic
	}
	if v := r.Version; v != nil && v.DataschemaXid != "" {
		if s, serr := doc.ResolveSchema(v.DataschemaXid); serr == nil {
			w.Contract = SuggestContractName(s.Schema.SchemaID)
		}
	}
	return w
}

// knownMessagesMessage builds the remediation line for an unknown message
// reference: close matches when the ref narrows the list, the full catalog
// when it does not. The registry is small enough that listing it is help,
// not noise.
func knownMessagesMessage(ref string, doc *xregistry.Export) string {
	ids := messageIDs(doc)
	var close []string
	for _, id := range ids {
		if strings.Contains(id, ref) {
			close = append(close, id)
		}
	}
	if len(close) > 0 {
		return "close matches: " + strings.Join(close, ", ")
	}
	if len(ids) > 0 {
		return "known messages: " + strings.Join(ids, ", ")
	}
	return "the registry declares no messages"
}

package template

import (
	"fmt"
	"path/filepath"
)

// The wiring vocabulary: the parameter names block templates record in
// their scaffold values and later commands (sys create/update, deploy,
// prompt suggestions) read back. They are CLI-owned convention, not
// manifest schema — a template that names its parameters otherwise simply
// gets no assembly or suggestions. One home so a vocabulary change has
// one diff, not a scavenger hunt.
const (
	KeyAppID        = "appId"
	KeyTopic        = "topic"
	KeyContract     = "contract"
	KeyPubsub       = "pubsub"
	KeyPort         = "port"
	KeyFromPort     = "fromPort"
	KeyToPort       = "toPort"
	KeyName         = "name"
	KeyOrganization = "organization"
	KeyProjectName  = "projectName"
	KeySystemClass  = "systemClass"

	// DefaultPubsub is the pub/sub component a record belongs to when it
	// predates the pubsub value being recorded.
	DefaultPubsub = "pubsub"
)

// RecordValue reads key from a scaffold record's values as a non-empty
// string. Missing, mistyped, and empty values are errors naming the
// record, so the user knows which project to fix. It is the strict
// regime: callers validating a workspace (system assembly) use it;
// callers offering suggestions use SoftValue instead.
func RecordValue(e ScaffoldEntry, key string) (string, error) {
	record := filepath.Join(e.Path, filepath.FromSlash(ScaffoldRelPath))
	v, ok := e.Values[key]
	if !ok {
		return "", fmt.Errorf("%s: values.%s is missing", record, key)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s has type %T, expected string", record, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s is empty", record, key)
	}
	return s, nil
}

// RecordValueDefault is RecordValue with a fallback for records that
// predate the value being recorded. Only a missing key falls back; a
// present but mistyped or empty value is still an error — a record that
// names the key must say something meaningful.
func RecordValueDefault(e ScaffoldEntry, key, fallback string) (string, error) {
	if _, ok := e.Values[key]; !ok {
		return fallback, nil
	}
	return RecordValue(e, key)
}

// SoftValue reads key from a values map as a non-empty string, reporting
// false for missing, mistyped, or empty values. It is the lenient regime:
// suggestion aids and best-effort joins skip such records rather than
// failing an operation the records themselves would still allow.
func SoftValue(values map[string]any, key string) (string, bool) {
	s, ok := values[key].(string)
	if !ok || s == "" {
		return "", false
	}
	return s, true
}
